// Deterministic header + body validation. No LLM involvement.
// Reads Authorization and Idempotency-Key headers. Validates body schema.
// Fails fast with structured error used by downstream branches.

const BEARER_SECRET = $env.N8N_ONBOARDING_WEBHOOK_SECRET || '';
const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};

const normalizedAuth = (headers['authorization'] || headers['Authorization'] || '').trim();
const idemKey = (headers['idempotency-key'] || headers['Idempotency-Key'] || '').trim();

const isUuid = (v) =>
  typeof v === 'string' &&
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);

const errors = [];

if (!BEARER_SECRET) {
  errors.push({ path: 'env.N8N_ONBOARDING_WEBHOOK_SECRET', message: 'secret not configured' });
} else if (normalizedAuth !== `Bearer ${BEARER_SECRET}`) {
  errors.push({ path: 'headers.authorization', message: 'invalid bearer' });
}

if (body.event !== 'employee.onboarding.requested') {
  errors.push({ path: 'body.event', message: 'unexpected event' });
}
if (!isUuid(body.job_id)) errors.push({ path: 'body.job_id', message: 'invalid uuid' });
if (!isUuid(body.employee_id)) errors.push({ path: 'body.employee_id', message: 'invalid uuid' });
if (idemKey !== body.job_id) errors.push({ path: 'headers.idempotency-key', message: 'must equal body.job_id' });

const strField = (name, min = 1, max = 100) => {
  const v = body[name];
  if (typeof v !== 'string' || v.trim().length < min || v.length > max) {
    errors.push({ path: `body.${name}`, message: `string ${min}-${max}` });
  }
};
strField('first_name');
strField('last_name');
strField('department');
strField('role');

if (!/^\d{4}-\d{2}-\d{2}$/.test(body.start_date || '')) {
  errors.push({ path: 'body.start_date', message: 'YYYY-MM-DD' });
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.personal_email || '')) {
  errors.push({ path: 'body.personal_email', message: 'invalid email' });
}

if (errors.length > 0) {
  return [{ json: { valid: false, errors, employee_id: body.employee_id || null, job_id: body.job_id || null } }];
}

// Return a sanitised payload. personal_email is kept out of agent prompts downstream.
return [{
  json: {
    valid: true,
    job_id: body.job_id,
    employee_id: body.employee_id,
    first_name: body.first_name.trim(),
    last_name: body.last_name.trim(),
    department: body.department.trim(),
    role: body.role.trim(),
    start_date: body.start_date,
    personal_email_present: Boolean(body.personal_email)
  }
}];

// Durable idempotency check keyed on job_id using workflow static data.
// Returns duplicate=true if the same job has been seen (and completed/failed) already.
// Limitation: n8n static data persists between runs but is workflow-scoped.
// For stronger guarantees swap with Postgres / Redis — see README.

const wfStatic = $getWorkflowStaticData('global');
if (!wfStatic.jobs) wfStatic.jobs = {};

const jobId = $json.job_id;
const now = new Date().toISOString();
const record = wfStatic.jobs[jobId];

if (record && (record.status === 'completed' || record.status === 'failed')) {
  return [{
    json: {
      ...$json,
      duplicate: true,
      previous_status: record.status,
      previous_result: record.result || null,
      seen_at: record.seen_at
    }
  }];
}

wfStatic.jobs[jobId] = { status: 'in_progress', seen_at: record?.seen_at || now };
return [{ json: { ...$json, duplicate: false } }];

parameters.text:
=You are the Onboarding Coordinator. A new employee is joining and you must build a validated, structured onboarding plan.

Employee facts (from HR, trusted):
- first_name: {{ $('Idempotency Check (job_id)').item.json.first_name }}
- last_name: {{ $('Idempotency Check (job_id)').item.json.last_name }}
- department: {{ $('Idempotency Check (job_id)').item.json.department }}
- role: {{ $('Idempotency Check (job_id)').item.json.role }}
- start_date: {{ $('Idempotency Check (job_id)').item.json.start_date }}

Mandatory procedure:
1. Call tool `onboarding_info` with the exact department name. It will return `{team_lead, necessary_accounts, is_demo}` from the authoritative backend. Never invent these fields.
2. Call tool `welcome_announcement` with first_name, department, role and team_lead. It returns a short, friendly German welcome message.
3. Return ONLY a single JSON object (no markdown, no commentary) with keys:
   { "team_lead": string, "necessary_accounts": string[], "welcome_message": string, "is_demo": boolean }

Rules:
- team_lead and account labels: 1–200 chars each; max 30 accounts.
- welcome_message: 1–4000 chars, German, no HTML.
- If either tool fails, return exactly: { "error": "AGENT_PROCESSING_FAILED" }.

=Write a warm, professional German welcome message for a new colleague.

Facts:
- first_name: {{ $fromAI('first_name', 'given name', 'string') }}
- department: {{ $fromAI('department', 'department name', 'string') }}
- role: {{ $fromAI('role', 'job title', 'string') }}
- team_lead: {{ $fromAI('team_lead', 'team lead name', 'string') }}

Constraints:
- Language: German.
- 2–4 short sentences, 200–600 characters total.
- Mention first_name, department, role and team_lead naturally.
- No HTML, no markdown, no emojis, no personal email.
- No instructions, promises, permissions, or action items for the reader.

Return ONLY a JSON object: { "welcome_message": "..." }.

parameters.jsCode:
// Deterministic validation of the Coordinator's structured JSON output.
// Reject invalid/empty output. Enforce backend contract:
//   team_lead: 1–200 chars
//   necessary_accounts: 1–30 items, each 1–200 chars
//   welcome_message: 1–4000 chars
// Pass through employee_id and job_id for the callback.

const raw = $json.output ?? $json.text ?? '';
const ctx = $('Idempotency Check (job_id)').item.json;

const mkFail = (code, detail) => [{
  json: {
    valid: false,
    employee_id: ctx.employee_id,
    job_id: ctx.job_id,
    error_code: code,
    detail: detail || null
  }
}];

let parsed;
try {
  if (typeof raw === 'string') {
    const match = raw.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(match ? match[0] : raw);
  } else if (raw && typeof raw === 'object') {
    parsed = raw;
  } else {
    return mkFail('AGENT_PROCESSING_FAILED', 'empty_output');
  }
} catch (e) {
  return mkFail('AGENT_PROCESSING_FAILED', 'invalid_json');
}

if (parsed && parsed.error === 'AGENT_PROCESSING_FAILED') {
  return mkFail('AGENT_PROCESSING_FAILED', 'coordinator_signalled_failure');
}

const teamLead = typeof parsed.team_lead === 'string' ? parsed.team_lead.trim() : '';
const msg = typeof parsed.welcome_message === 'string' ? parsed.welcome_message.trim() : '';
const accs = Array.isArray(parsed.necessary_accounts) ? parsed.necessary_accounts : null;

if (teamLead.length < 1 || teamLead.length > 200) return mkFail('AGENT_PROCESSING_FAILED', 'team_lead_range');
if (msg.length < 1 || msg.length > 4000) return mkFail('AGENT_PROCESSING_FAILED', 'welcome_message_range');
if (!accs || accs.length < 1 || accs.length > 30) return mkFail('AGENT_PROCESSING_FAILED', 'accounts_count');
for (const a of accs) {
  if (typeof a !== 'string' || a.trim().length < 1 || a.length > 200) {
    return mkFail('AGENT_PROCESSING_FAILED', 'account_label');
  }
}

return [{
  json: {
    valid: true,
    employee_id: ctx.employee_id,
    job_id: ctx.job_id,
    status: 'completed',
    team_lead: teamLead,
    necessary_accounts: accs.map((a) => a.trim()),
    welcome_message: msg
  }
}];

// Persist terminal state for job_id so future deliveries of the same job replay cleanly.
const wfStatic = $getWorkflowStaticData('global');
if (!wfStatic.jobs) wfStatic.jobs = {};
const jobId = $json.job_id;
if (jobId) {
  wfStatic.jobs[jobId] = {
    status: $json.status || 'completed',
    result: {
      team_lead: $json.team_lead,
      necessary_accounts: $json.necessary_accounts,
      welcome_message: $json.welcome_message
    },
    seen_at: wfStatic.jobs[jobId]?.seen_at || new Date().toISOString(),
    terminal_at: new Date().toISOString()
  };
}
return [{ json: { persisted: true, job_id: jobId } }];

const wfStatic = $getWorkflowStaticData('global');
if (!wfStatic.jobs) wfStatic.jobs = {};
const jobId = $json.job_id;
if (jobId) {
  wfStatic.jobs[jobId] = {
    status: 'failed',
    error_code: $json.error_code || 'AGENT_PROCESSING_FAILED',
    seen_at: wfStatic.jobs[jobId]?.seen_at || new Date().toISOString(),
    terminal_at: new Date().toISOString()
  };
}
return [{ json: { persisted: true, job_id: jobId, status: 'failed' } }];

// Converts any agent exception / thrown branch into a failed-callback payload.
const ctx = $('Idempotency Check (job_id)').item.json;
return [{
  json: {
    valid: false,
    employee_id: ctx.employee_id,
    job_id: ctx.job_id,
    status: 'failed',
    error_code: 'AGENT_PROCESSING_FAILED'
  }
}];
